// types/domain.ts

/**
 * DOMAIN TYPES
 *
 * This file contains the main types that represent EcoShop's business
 * entities. All types here are based on the Prisma schema
 * and are used throughout the application (frontend and backend).
 *
 * These types must NOT contain validation or transformation logic —
 * only data structure definitions.
 */

/**
 * Represents a photo associated with a product.
 * Photos are stored on the file system in public/data_fotos/
 */
export interface Photo {
  /** Unique file name generated by the system (e.g. "123_abc123.jpg") */
  nome: string;
  /** Public URL to access the photo via the browser */
  url: string;
}

/**
 * API response when listing a product's photos.
 * Returned by the GET /api/produtos/{id}/fotos endpoints
 */
export interface PhotosResponse {
  /** Array of photos found for the product */
  fotos: Photo[];
  /** Quantidade total de fotos (equivalente a fotos.length) */
  total: number;
  /** ID of the product the photos belong to */
  produtoId: number;
}

/**
 * Sustainable product available in the catalog.
 * Core of the application — represents items for sale on the platform.
 */
export interface Product {
  id: number;
  /** Name shown in the product listing and detail */
  nome: string;
  /** Detailed description of the product and its sustainable attributes */
  descricao?: string;
  /** Price in reais (BRL). Stored as Decimal in the database, serialized as number in the API */
  preco: number;
  /** URL of the product's main image (optional, can be null) */
  fotoUrl?: string;
  /** Foreign key referencing the product's category */
  categoriaId: number;
  /** Foreign key referencing the brand/manufacturer */
  marcaId: number;
  /** Date the product was registered in the system */
  criadoEm: Date;
  /** Relationship with the Categoria entity (populated when include.categoria is true) */
  categoria?: Category;
  /** Relationship with the Marca entity (populated when include.marca is true) */
  marca?: Brand;
  /** List of certifications linked to this product (many-to-many relationship) */
  certificados?: ProductCertificate[];
}

/**
 * Product category (e.g. "Sustainable Clothing", "Organic Food").
 * Used to group similar products and filter in the frontend.
 */
export interface Category {
  id: number;
  /** Unique category name (e.g. "Natural Cosmetics") */
  nome: string;
  /** Optional description explaining what the category covers */
  descricao?: string;
}

/**
 * Approval status of a brand request (ADR-0018).
 * PENDENTE: public registration awaiting approval from an ADMIN.
 * APROVADA: brand released (includes those created directly by the ADMIN in the panel).
 * REJEITADA: reserved for future use; no flow produces it yet.
 */
export type BrandStatus = "PENDENTE" | "APROVADA" | "REJEITADA";

/**
 * Brand or manufacturer of sustainable products.
 * Each brand is associated with a user of type "MARCA" or "ADMIN".
 */
export interface Brand {
  id: number;
  /** Brand name (e.g. "EcoBrand", "Pureza Naturais") */
  nome: string;
  /** Brand description, its story and sustainable commitments */
  descricao?: string;
  /** Approval status of the brand request (ADR-0018) */
  status: BrandStatus;
  /** ID of the user responsible for the brand (owner or administrator) */
  usuarioId: number;
  /** Summary data of the responsible user (populated via include.usuario) */
  usuario?: UserSummary;
  /** List of this brand's products (populated via include.produtos) */
  produtos?: Product[];
}

/**
 * Sustainability certification (e.g. "FSC", "Organic Brazil", "Eureciclo").
 * They attest that the product meets strict environmental standards.
 */
export interface Certificate {
  id: number;
  /** Certificate name (e.g. "Cruelty Free") — unique in the system */
  nome: string;
  /** Detailed description of what the certificate guarantees */
  descricao?: string;
  /** Body or entity that issues the certificate (e.g. "PETA", "SisOrg") */
  orgaoEmissor: string;
}

/**
 * Many-to-many relationship between Produto and Certificado.
 * A product can have multiple certificates.
 * A certificate can be assigned to multiple products.
 */
export interface ProductCertificate {
  produtoId: number;
  certificadoId: number;
  /** Full certificate data (populated via include.certificado) */
  certificado: Certificate;
}

/**
 * Complete system user.
 * Includes all sensitive fields — must NOT be exposed in public APIs.
 * For API responses, prefer UserSummary when possible.
 */
export interface User {
  id: number;
  nome: string;
  email: string; // unique in the system, used for login
  telefone?: string;
  tipo: UserType; // ADMIN, CLIENTE, or MARCA
  criadoEm: Date;
}

/**
 * Summarized version of the user for API responses.
 * Excludes sensitive fields (password, full phone?) and is safe to
 * return from endpoints that need to identify the responsible person.
 */
export interface UserSummary {
  id: number;
  nome: string;
  email: string;
}

/**
 * User roles available in the system.
 * - ADMIN: Full access to the admin panel and all operations
 * - CLIENTE: Regular user who can shop and use EcoScan AI
 * - MARCA: Brand representative who can manage their products
 */
export type UserType = "CLIENTE" | "MARCA" | "ADMIN";
